let pointer=null;
function addPlant(id,r,c){const spec=plants.find(p=>p.id===id);if(!spec||plantsOn.some(p=>p.r===r&&p.c===c))return false;if(sun<spec.cost){showToast('Нужно больше солнышек ☀️');return false}sun-=spec.cost;const p={id,r,c,hp:spec.hp,maxHp:spec.hp,cool:rand(.2,1.1),bob:rand(0,6),armed:false,arm:4.5,bite:0};plantsOn.push(p);if(id==='cherry'){p.fuse=.55;showToast('Бум! Вишня готовится 🍒')}if(id==='mine')showToast('Картошка зарыта — подожди немного');updateHud();return true}
function startGame(which=mode){mode=which;plantsOn=[];zombies=[];shots=[];suns=[];particles=[];sun=which==='night'?100:150;wave=1;score=0;spawned=0;totalZombies=which==='endless'?99:18;spawnTimer=2;lawnMowers=Array.from({length:ROWS},(_,r)=>({x:cellW*.48,y:boardY(r),used:false,active:false}));selected=null;shovel=false;paused=false;gameState='playing';ui.overlay.style.display='none';ui.status.textContent=which==='bowling'?'Выбирай орехи и катай их по дорожкам!':'Расставь растения — не пропусти их!';ui.hint.textContent='☀️ нажми, чтобы собрать';document.getElementById('pauseBtn').textContent='Ⅱ';updateHud();showFlash('ВОЛНА 1 — ОНИ УЖЕ ИДУТ!');}
function showFlash(text){ui.flash.innerHTML=text;ui.flash.classList.add('show');setTimeout(()=>ui.flash.classList.remove('show'),1250)}
function spawnZombie(){const r=Math.floor(rand(0,ROWS)),type=mode==='night'&&Math.random()<.35?zombieTypes[2]:zombieTypes[Math.floor(rand(0,Math.min(zombieTypes.length,2+Math.floor(wave/2))))];const boost=mode==='endless'?1+Math.floor(wave/4)*.2:1;zombies.push({r,x:W+cellW*.25,type,hp:type.hp*boost,maxHp:type.hp*boost,speed:type.speed*(mode==='night'?1.1:1),walk:rand(0,7),attack:0,slowTimer:0,hitFlash:false});}
function update(dt){if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}if(gameState!=='playing'||paused)return;
// sun production + sky drops
for(const p of plantsOn){p.bob+=dt*3;if(p.id==='sun'){p.cool-=dt;if(p.cool<=0){p.cool=p.interval+rand(-.8,1);suns.push({x:boardX(p.c)+rand(-cellW*.2,cellW*.2),y:boardY(p.r)-cellH*.25,radius:Math.min(14,cellH*.14),life:13,spin:0,fromPlant:true})}}if(p.id==='mine'&&!p.armed){p.arm-=dt;if(p.arm<=0)p.armed=true}if(p.id==='cherry'&&p.fuse>0){p.fuse-=dt;if(p.fuse<=0){for(const z of zombies)if(Math.abs(z.x-boardX(p.c))<cellW*1.65&&Math.abs(z.r-p.r)<=1)z.hp-=500;blast(boardX(p.c),boardY(p.r),'💥',12);p.hp=0}}
if(p.id==='pea'||p.id==='snow'||p.id==='double'){p.cool-=dt;if(p.cool<=0&&zombies.some(z=>z.r===p.r&&z.x>boardX(p.c))){p.cool=plants.find(q=>q.id===p.id).interval;const n=p.id==='double'?2:1;for(let i=0;i<n;i++)shots.push({x:boardX(p.c)+cellW*.21,y:boardY(p.r)-cellH*.05-i*4,r:p.r,damage:p.id==='snow'?22:25,slow:p.id==='snow',speed:cellW*1.15})}}
if(p.id==='chomp'){p.bite-=dt;if(p.bite<=0){const target=zombies.find(z=>z.r===p.r&&z.x-boardX(p.c)<cellW*.48&&z.x>boardX(p.c)-cellW*.3);if(target){target.hp=0;p.bite=4.5;blast(target.x,boardY(target.r),'✨',5)}}}
if(p.id==='mine'&&p.armed){const z=zombies.find(z=>z.r===p.r&&Math.abs(z.x-boardX(p.c))<cellW*.38);if(z){z.hp=0;blast(boardX(p.c),boardY(p.r),'💥',7);p.hp=0}}
}
spawnTimer-=dt;if(spawned<totalZombies&&spawnTimer<=0){spawnZombie();spawned++;const base=mode==='endless'?Math.max(1.4,5.3-wave*.3):Math.max(2.2,5.4-wave*.7);spawnTimer=base*rand(.75,1.25);if(spawned%6===0&&mode!=='endless'){wave=Math.min(3,Math.floor(spawned/6)+1);showFlash(`WAVE ${wave} — ПО ТРОПИНКЕ!`);updateHud()}}
for(const sh of shots){sh.x+=sh.speed*dt;const z=zombies.find(z=>z.r===sh.r&&Math.abs(z.x-sh.x)<cellW*.22);if(z){z.hp-=sh.damage;z.hitFlash=true;setTimeout(()=>z.hitFlash=false,70);if(sh.slow){z.slowTimer=2.2;z.speed=z.type.speed*.55}sh.dead=true;particles.push({x:sh.x,y:sh.y,life:.3,size:14,text:'✦'})}}
shots=shots.filter(s=>!s.dead&&s.x<W+20);
for(const z of zombies){z.walk+=dt*7;if(z.slowTimer>0)z.slowTimer-=dt;const target=plantsOn.find(p=>p.r===z.r&&Math.abs(z.x-(boardX(p.c)+cellW*.2))<cellW*.36&&p.hp>0);if(target){z.attack-=dt;if(z.attack<=0){target.hp-=22;z.attack=.7;particles.push({x:boardX(target.c),y:boardY(target.r)-cellH*.23,life:.35,size:13,text:'💢'})}}else z.x-=z.speed*(z.slowTimer>0?.55:1)*dt;
const mower=lawnMowers[z.r];if(z.x<cellW*.55&&mower&&!mower.used){mower.used=true;mower.active=true}if(z.x<-cellW*.3){gameState='lost';showEnd(false);return}}
for(const m of lawnMowers){if(m.active){m.x+=cellW*2.7*dt;for(const z of zombies)if(z.r===lawnMowers.indexOf(m)&&z.x<m.x+cellW*.5)z.hp=0;if(m.x>W+cellW)m.active=false}}
zombies=zombies.filter(z=>{if(z.hp<=0){sun+=z.type.reward;score++;particles.push({x:z.x,y:boardY(z.r)-cellH*.3,life:.9,size:17,text:'☀️'});return false}return true});
plantsOn=plantsOn.filter(p=>p.hp>0);
for(const s of suns){s.life-=dt;s.spin+=dt*.7;if(s.fromPlant)s.y+=Math.sin(s.spin*2)*dt*2;else s.y+=dt*3}suns=suns.filter(s=>s.life>0);
for(const p of particles){p.y-=dt*22;p.life-=dt}particles=particles.filter(p=>p.life>0);
if(mode!=='endless'&&spawned>=totalZombies&&zombies.length===0){gameState='won';showEnd(true)}updateHud();}
function blast(x,y,text,n){for(let i=0;i<n;i++)particles.push({x:x+rand(-cellW*.45,cellW*.45),y:y+rand(-cellH*.25,cellH*.25),life:rand(.5,1.2),size:rand(16,28),text})}
function loop(t){const dt=Math.min(.04,(t-last)/1000||0);last=t;update(dt);drawBoard();requestAnimationFrame(loop)}requestAnimationFrame(loop);
canvas.addEventListener('pointermove',e=>{const b=canvas.getBoundingClientRect();const c=Math.floor((e.clientX-b.left)/cellW),r=Math.floor((e.clientY-b.top)/cellH);pointer=c>=0&&c<COLS&&r>=0&&r<ROWS?{c,r}:null});
canvas.addEventListener('pointerdown',e=>{e.preventDefault();const b=canvas.getBoundingClientRect(),x=e.clientX-b.left,y=e.clientY-b.top;for(let i=suns.length-1;i>=0;i--){const s=suns[i];if(Math.hypot(s.x-x,s.y-y)<Math.max(24,s.radius+12)){sun+=25;suns.splice(i,1);updateHud();if(sound)beep(680,.07);return}}if(gameState!=='playing'||paused)return;const c=Math.floor(x/cellW),r=Math.floor(y/cellH);if(c<0||c>=COLS||r<0||r>=ROWS)return;if(shovel){const p=plantsOn.find(p=>p.c===c&&p.r===r);if(p){plantsOn=plantsOn.filter(q=>q!==p);sun+=Math.floor(plants.find(q=>q.id===p.id).cost*.4);showToast('Растение убрано');updateHud()}shovel=false;updateHud();return}if(!selected){showToast('Выбери растение на карточке');return}if(plantsOn.some(p=>p.c===c&&p.r===r)){showToast('Здесь уже кто-то растёт!');return}addPlant(selected,r,c);selected=null;updateHud();if(sound)beep(390,.05)});

