--- index.html
+++ index.html
@@ -99,9 +99,9 @@
 function menuMarkup(){return `<div class="modal"><div class="hero">🌻 🧟‍♂️ 🌱</div><div class="eyebrow">Соседский дозор · сад 01</div><h1>Зомби уже<br>за забором!</h1><p>Собирай солнышки, сажай защитников и не дай нежити добраться до дома. Все дорожки на виду — играй одним пальцем.</p><div class="mode-grid"><button class="mode-choice active" data-mode="garden">🌼 Двор</button><button class="mode-choice" data-mode="night">🌙 Ночь</button><button class="mode-choice" data-mode="bowling">🥔 Орехобол</button><button class="mode-choice" data-mode="endless">♾️ Выживание</button></div><button class="modal-btn" id="startBtn">НАЧАТЬ ЗАЩИТУ →</button></div>`}
